    number: 61,
    text: `Клетки нашего мозга в буквальном смысле питаются информацией, записывая это в себе, но спустя время ее испражняют. Это так называемый информационный метаболизм, когда мы получаем впечатления, эмоции, информацию, а потом спускаем в канализацию.

Если же человек начинает поглощаться самим собой, информация о себе никуда не девается и не заменяется на новую, а тут же поглощается снова. Фактически ваши клетки начинают питаться собственными фекалиями.

Возникает интоксикация, которая воспринимается как страдание, усталость, депрессия, апатия. Именно поэтому работа, действие, путешествия, встречи, знакомства разрывают этот круг пожирания собственных отходов.`,
